const input=$json.body??$json;
const closeout=String(input.closeout_status??input.status??'').toLowerCase();
const dealId=input.deal_id,leadId=input.lead_id,propertyId=input.property_id;
const gross=Number(input.gross_profit??0),costs=Number(input.closing_costs??0),net=Number(input.net_profit??0);
const sampleSize=Number(input.historical_sample_size??input.sample_size??0);
const exitStrategy=String(input.exit_strategy??'assignment').trim();
const margin=gross?net/gross:null;
const blockers=Array.isArray(input.blockers)?input.blockers:[];
let performance_status='needs_review',next='WF-126',reason='portfolio performance record requires review';
if(input.dnc===true){performance_status='blocked_dnc';reason='DNC/contact restriction';}
else if(blockers.length){performance_status='blocked';reason='active performance blockers';}
else if(closeout!=='closeout_ready'&&closeout!=='negative_profit_review'){performance_status='closeout_not_ready';next='WF-329';reason='final CRM closeout is not confirmed';}
else if(!dealId||!leadId||!propertyId){performance_status='incomplete_identity';reason='deal/property/lead identity incomplete';}
else if(!Number.isFinite(gross)||!Number.isFinite(costs)||!Number.isFinite(net)){performance_status='profit_inputs_invalid';reason='profit inputs are invalid';}
else{performance_status='performance_record_ready';next='WF-331';reason='verified closeout profit data is ready for portfolio performance and underwriting feedback';}
const signal=net>0?'positive':net<0?'negative':'neutral';
const feedback={net_profit:net,profit_margin:margin,exit_strategy:exitStrategy,historical_sample_size:sampleSize,performance_signal:signal,underwriting_feedback_signal:net>0?'consider_positive_calibration':net<0?'consider_downward_calibration':'hold_calibration'};
return [{json:{...input,workflow_id:'WF-330',workflow_name:'Final CRM Closeout → Portfolio Performance Record & Underwriting Feedback Controller',performance_status,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,gross_profit:gross,closing_costs:costs,net_profit:net,profit_margin:margin,historical_sample_size:sampleSize,performance_signal:signal,underwriting_feedback:feedback,next_workflow:next,human_review_required:performance_status!=='performance_record_ready',crm_activity:{activity_type:'portfolio_performance_record',deal_id:dealId,lead_id:leadId,property_id:propertyId,status:performance_status,gross_profit:gross,closing_costs:costs,net_profit:net,profit_margin:margin,historical_sample_size:sampleSize,reason}}}];
